/**
 * @name Path injection
 * @kind path-problem
 * @problem.severity error
 * @id py/custom-path-injection
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module Cfg implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node s) { s instanceof RemoteFlowSource }
  predicate isSink(DataFlow::Node s) { s = any(FileSystemAccess fa).getAPathArgument() }
}
module F = TaintTracking::Global<Cfg>;
import F::PathGraph

from F::PathNode source, F::PathNode sink
where F::flowPath(source, sink)
select sink.getNode(), source, sink, "Path from $@.", source.getNode(), "user input"
